struct DoCreateFolder {
    parent_id: String,
    name: String,
}

impl<ServerT: ServerType> DoOperation<XpComGraphClient<ServerT>, XpComGraphError>
    for DoCreateFolder
{
    const NAME: &'static str = "create folder";
    type Okay = String;
    type Listener = SafeExchangeSimpleOperationListener;

    async fn do_operation(
        &mut self,
        client: &XpComGraphClient<ServerT>,
    ) -> Result<Self::Okay, XpComGraphError> {
        let folder_config = MailFolder {
            display_name: notnull!(self.name.clone()),
            ..Default::default()
        };
        let base_api_url = client.base_api_url()?;
        let request = child_folders::Post::new(
            base_api_url.to_string(),
            self.parent_id.clone(),
            OperationBody::JSON(folder_config),
        );

        let folder = client
            .send_request_json_response(request, Default::default())
            .await?;
        let folder_id = folder.entity.id.required("folder id")?;
        Ok(folder_id)
    }

    fn into_success_arg(
        self,
        folder_id: Self::Okay,
    ) -> <Self::Listener as SafeListener>::OnSuccessArg {
        (std::iter::once(folder_id), UseLegacyFallback::No).into()
    }

    fn into_failure_arg(self) {}
}

impl<ServerT: ServerType> XpComGraphClient<ServerT> {
    pub(crate) async fn create_folder(
        self: Arc<XpComGraphClient<ServerT>>,
        listener: SafeExchangeSimpleOperationListener,
        parent_id: String,
        name: String,
    ) {
        let operation = DoCreateFolder { parent_id, name };
        operation.handle_operation(&self, &listener).await;
    }
